const seen = new Set();
return $input.all().map((item, index) => {
  const input = item.json;
  const id = typeof input.id === 'string' ? input.id.trim() : '';
  const errors = [];
  if (!/^[A-Z]-\d{3}$/.test(id)) errors.push('INVALID_ID');
  if (id && seen.has(id)) errors.push('DUPLICATE_ID');
  if (id) seen.add(id);
  const amount = String(input.amount ?? '').trim();
  if (!/^(?:0|[1-9]\d*)(?:\.\d{1,2})?$/.test(amount)) errors.push('INVALID_AMOUNT');
  if (typeof input.email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(input.email)) errors.push('INVALID_EMAIL');
  return {json:{row:index + 1,id,amount,accepted:errors.length===0,errors}};
});

const rows = $input.all().map(item => item.json);
const accepted = rows.filter(row => row.accepted);
const rejected = rows.filter(row => !row.accepted);
const errorCounts = {};
for (const row of rejected) for (const code of row.errors) errorCounts[code]=(errorCounts[code]??0)+1;
return [{json:{project:'VYRA n8n Offline Validation Demo',synthetic:true,records:rows.length,accepted:accepted.length,rejected:rejected.length,errorCounts,rows}}];

const summary = $input.first().json;
if (summary.records !== 5 || summary.accepted !== 3 || summary.rejected !== 2) {
  throw new Error('Unexpected demo fixture results');
}
if (summary.errorCounts.DUPLICATE_ID !== 1 || summary.errorCounts.INVALID_AMOUNT !== 1) {
  throw new Error('Unexpected error classes');
}
return [{json:{...summary,qa:'FIXTURE_ASSERTIONS_PASSED'}}];
